const widgetMedianFirstResponse = `-- name: WidgetMedianFirstResponse :one
SELECT COALESCE(percentile_cont(0.5) WITHIN GROUP (ORDER BY extract(epoch FROM first_response_at - created_at)), -1)::float8 AS seconds
FROM conversations
WHERE organization_id = $1 AND channel_instance_id = $2
  AND first_response_at IS NOT NULL AND first_response_at >= created_at
  AND created_at > now() - interval '14 days' AND deleted_at IS NULL
`

type WidgetMedianFirstResponseParams struct {
	OrganizationID    int64       `json:"organization_id"`
	ChannelInstanceID pgtype.Int8 `json:"channel_instance_id"`
}

// Median first response (seconds) of the widget's conversations of the last
// 14 days; -1 without answered conversations.
func (q *Queries) WidgetMedianFirstResponse(ctx context.Context, arg WidgetMedianFirstResponseParams) (float64, error) {
	row := q.db.QueryRow(ctx, widgetMedianFirstResponse, arg.OrganizationID, arg.ChannelInstanceID)
	var seconds float64
	err := row.Scan(&seconds)
	return seconds, err
}
